with with_window as (select a.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from sessions a left join subscriptions sub on a.customer_id = sub.customer_id and a.started_at >= sub.start_date and a.started_at < sub.end_date + interval '14' day), attributed as (select a.*, sub.id as subscription_id_2, sub.plan as subscription_plan, sub.monthly_fee as subscription_monthly_fee from with_window a left join subscriptions sub on a.customer_id = sub.customer_id and a.started_at between sub.start_date and sub.end_date), remaining_keys as (select device from attributed except distinct select device from sessions where device in ('desktop', 'mobile')), reconciled as (select s.* from attributed s join remaining_keys k on s.device = k.device) select case when subscription_id_2 >= 10 then 'PREMIUM' else 'STANDARD' end as subscription_id_2_tier, date_trunc('quarter', started_at) as quarter_start, round(sum(subscription_id_2) / nullif(count(case when browser = 'Firefox' then 1 end), 0), 2) as subscription_id_2_per_firefox, round(sum(subscription_monthly_fee) / nullif(count(case when country = 'JP' then 1 end), 0), 2) as subscription_monthly_fee_per_jp, approx_percentile(subscription_id, 0.9) as subscription_id_p90, dense_rank() over (partition by case when subscription_id_2 >= 10 then 'PREMIUM' else 'STANDARD' end order by round(sum(subscription_monthly_fee) / nullif(count(case when country = 'JP' then 1 end), 0), 2) desc) as subscription_monthly_fee_per_jp_dense_rank from reconciled group by 1, 2 order by subscription_monthly_fee_per_jp
